@Test
public void testExecuteStatements() throws Exception {
    String tenantId = getOrganizationId();
    String tableName = initATableValues(tenantId, getDefaultSplits(tenantId), getUrl());
    String ptsdbTableName = generateUniqueName();
    String statements = // Shouldn't error out b/c of if not exists clause
    "create table if not exists " + tableName + "   (organization_id char(15) not null, \n" + "    entity_id char(15) not null,\n" + "    a_string varchar(100),\n" + "    b_string varchar(100)\n" + "    CONSTRAINT pk PRIMARY KEY (organization_id,entity_id));\n" + "create table " + ptsdbTableName + "   (inst varchar null,\n" + "    host varchar null,\n" + "    \"DATE\" date not null,\n" + "    val decimal\n" + "    CONSTRAINT pk PRIMARY KEY (inst,host,\"DATE\"))\n" + "    split on (?,?,?);\n" + "alter table " + ptsdbTableName + // Shouldn't error out b/c of if not exists clause
    " add if not exists val decimal;\n" + "alter table " + ptsdbTableName + // Shouldn't error out b/c of if exists clause
    " drop column if exists blah;\n" + // Shouldn't error out b/c of if exists clause
    "drop table if exists FOO.BAR;\n" + "UPSERT INTO " + ptsdbTableName + "(\"DATE\", val, host) " + "    SELECT current_date(), x_integer+2, entity_id FROM " + tableName + " WHERE a_integer >= ?;" + "UPSERT INTO " + ptsdbTableName + "(\"DATE\", val, inst)\n" + "    SELECT \"DATE\"+1, val*10, host FROM " + ptsdbTableName + ";";
    Date now = new Date(System.currentTimeMillis());
    Connection conn = DriverManager.getConnection(getUrl());
    conn.setAutoCommit(true);
    List<Object> binds = Arrays.<Object>asList("a", "j", "s", 6);
    int nStatements = PhoenixRuntime.executeStatements(conn, new StringReader(statements), binds);
    assertEquals(7, nStatements);
    Date then = new Date(System.currentTimeMillis() + QueryConstants.MILLIS_IN_DAY);
    String query = "SELECT host,inst,\"DATE\",val FROM " + ptsdbTableName + " where inst is not null";
    PreparedStatement statement = conn.prepareStatement(query);
    ResultSet rs = statement.executeQuery();
    assertTrue(rs.next());
    assertEquals(null, rs.getString(1));
    assertEquals(ROW6, rs.getString(2));
    assertTrue(rs.getDate(3).after(now) && rs.getDate(3).before(then));
    assertEquals(null, rs.getBigDecimal(4));
    assertTrue(rs.next());
    assertEquals(null, rs.getString(1));
    assertEquals(ROW7, rs.getString(2));
    assertTrue(rs.getDate(3).after(now) && rs.getDate(3).before(then));
    assertTrue(BigDecimal.valueOf(70).compareTo(rs.getBigDecimal(4)) == 0);
    assertTrue(rs.next());
    assertEquals(null, rs.getString(1));
    assertEquals(ROW8, rs.getString(2));
    assertTrue(rs.getDate(3).after(now) && rs.getDate(3).before(then));
    assertTrue(BigDecimal.valueOf(60).compareTo(rs.getBigDecimal(4)) == 0);
    assertTrue(rs.next());
    assertEquals(null, rs.getString(1));
    assertEquals(ROW9, rs.getString(2));
    assertTrue(rs.getDate(3).after(now) && rs.getDate(3).before(then));
    assertTrue(BigDecimal.valueOf(50).compareTo(rs.getBigDecimal(4)) == 0);
    assertFalse(rs.next());
    conn.close();
}

@Test
public void testCharPadding() throws Exception {
    Connection conn = DriverManager.getConnection(getUrl());
    String tableName = generateUniqueName();
    String rowKey = "hello";
    String testString = "world";
    String query = "create table " + tableName + "(a_id integer not null, \n" + "a_string char(10) not null, \n" + "b_string char(8)\n" + "CONSTRAINT my_pk PRIMARY KEY (a_id, a_string))";
    PreparedStatement statement = conn.prepareStatement(query);
    statement.execute();
    statement = conn.prepareStatement("upsert into " + tableName + "    (a_id, " + "    a_string, " + "    b_string)" + "VALUES (?, ?, ?)");
    statement.setInt(1, 1);
    statement.setString(2, rowKey);
    statement.setString(3, testString);
    statement.execute();
    conn.commit();
    String btableName = generateUniqueName();
    ensureTableCreated(getUrl(), btableName, BTABLE_NAME, nextTimestamp() - 2);
    statement = conn.prepareStatement("upsert into " + btableName + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
    statement.setString(1, "abc");
    statement.setString(2, "xyz");
    statement.setString(3, "x");
    statement.setInt(4, 9);
    statement.setString(5, "ab");
    statement.setInt(6, 1);
    statement.setInt(7, 1);
    statement.setString(8, "ab");
    statement.setString(9, "morning1");
    statement.execute();
    conn.commit();
    try {
        // test rowkey and non-rowkey values in select statement
        query = "select a_string, b_string from " + tableName;
        assertCharacterPadding(conn.prepareStatement(query), rowKey, testString);
        // test with rowkey  in where clause
        query = "select a_string, b_string from " + tableName + " where a_id = 1 and a_string = '" + rowKey + "'";
        assertCharacterPadding(conn.prepareStatement(query), rowKey, testString);
        // test with non-rowkey  in where clause
        query = "select a_string, b_string from " + tableName + " where b_string = '" + testString + "'";
        assertCharacterPadding(conn.prepareStatement(query), rowKey, testString);
        // test with rowkey and id  in where clause
        query = "select a_string, b_string from " + tableName + " where a_id = 1 and a_string = '" + rowKey + "'";
        assertCharacterPadding(conn.prepareStatement(query), rowKey, testString);
        // test with rowkey and id  in where clause where rowkey is greater than the length of the char.len
        query = "select a_string, b_string from " + tableName + " where a_id = 1 and a_string  = '" + rowKey + testString + "'";
        statement = conn.prepareStatement(query);
        ResultSet rs = statement.executeQuery();
        assertFalse(rs.next());
        // test with rowkey and id  in where clause where rowkey is lesser than the length of the char.len
        query = "select a_string, b_string from " + tableName + " where a_id = 1 and a_string  = 'he'";
        statement = conn.prepareStatement(query);
        rs = statement.executeQuery();
        assertFalse(rs.next());
        String rowKey2 = "good";
        String testString2 = "morning";
        String testString8Char = "morning1";
        String testString10Char = "morning123";
        String upsert = "UPSERT INTO " + tableName + " values (2, '" + rowKey2 + "', '" + testString2 + "') ";
        statement = conn.prepareStatement(upsert);
        statement.execute();
        conn.commit();
        // test upsert statement with padding
        String tenantId = getOrganizationId();
        String atableName = initATableValues(tenantId, getDefaultSplits(tenantId), getUrl());
        upsert = "UPSERT INTO " + tableName + "(a_id, a_string, b_string) " + "SELECT A_INTEGER, A_STRING, B_STRING FROM " + atableName + " WHERE a_string = ?";
        statement = conn.prepareStatement(upsert);
        statement.setString(1, A_VALUE);
        int rowsInserted = statement.executeUpdate();
        assertEquals(4, rowsInserted);
        conn.commit();
        query = "select a_string, b_string from " + tableName + " where a_string  = '" + A_VALUE + "'";
        assertCharacterPadding(conn.prepareStatement(query), A_VALUE, B_VALUE);
        upsert = "UPSERT INTO " + tableName + " values (3, '" + testString2 + "', '" + testString2 + "') ";
        statement = conn.prepareStatement(upsert);
        statement.execute();
        conn.commit();
        query = "select a_string, b_string from " + tableName + "  where a_id = 3 and a_string = b_string";
        assertCharacterPadding(conn.prepareStatement(query), testString2, testString2);
        // compare a higher length col with lower length : a_string(10), b_string(8)
        query = "select a_string, b_string from " + tableName + "  where a_id = 3 and b_string = a_string";
        statement = conn.prepareStatement(query);
        statement.executeQuery();
        assertCharacterPadding(conn.prepareStatement(query), testString2, testString2);
        upsert = "UPSERT INTO " + tableName + " values (4, '" + rowKey2 + "', '" + rowKey2 + "') ";
        statement = conn.prepareStatement(upsert);
        statement.execute();
        conn.commit();
        // where both the columns have same value with different paddings
        query = "select a_string, b_string from " + tableName + "  where a_id = 4 and b_string = a_string";
        assertCharacterPadding(conn.prepareStatement(query), rowKey2, rowKey2);
        upsert = "UPSERT INTO " + tableName + " values (5, '" + testString10Char + "', '" + testString8Char + "') ";
        statement = conn.prepareStatement(upsert);
        statement.execute();
        conn.commit();
        // where smaller column is the subset of larger string
        query = "select a_string, b_string from " + tableName + "  where a_id = 5 and b_string = a_string";
        statement = conn.prepareStatement(query);
        rs = statement.executeQuery();
        assertFalse(rs.next());
        //where selecting from a CHAR(x) and upserting into a CHAR(y) where x>y
        // upsert rowkey value greater than rowkey limit
        try {
            upsert = "UPSERT INTO " + tableName + "(a_id, a_string, b_string) " + "SELECT x_integer, organization_id, b_string FROM " + atableName + " WHERE a_string = ?";
            statement = conn.prepareStatement(upsert);
            statement.setString(1, A_VALUE);
            statement.executeUpdate();
            fail("Should fail when bigger than expected character is inserted");
        } catch (SQLException ex) {
            assertEquals(SQLExceptionCode.DATA_EXCEEDS_MAX_CAPACITY.getErrorCode(), ex.getErrorCode());
        }
        // upsert non-rowkey value greater than its limit
        try {
            upsert = "UPSERT INTO " + tableName + "(a_id, a_string, b_string) " + "SELECT y_integer, a_string, entity_id FROM " + atableName + " WHERE a_string = ?";
            statement = conn.prepareStatement(upsert);
            statement.setString(1, A_VALUE);
            statement.executeUpdate();
            fail("Should fail when bigger than expected character is inserted");
        } catch (SQLException ex) {
            assertEquals(SQLExceptionCode.DATA_EXCEEDS_MAX_CAPACITY.getErrorCode(), ex.getErrorCode());
        }
        //where selecting from a CHAR(x) and upserting into a CHAR(y) where x<=y.
        upsert = "UPSERT INTO " + tableName + "(a_id, a_string, b_string) " + "SELECT a_integer, e_string, a_id FROM " + btableName;
        statement = conn.prepareStatement(upsert);
        rowsInserted = statement.executeUpdate();
        assertEquals(1, rowsInserted);
        conn.commit();
        query = "select a_string, b_string from " + tableName + " where a_string  = 'morning1'";
        assertCharacterPadding(conn.prepareStatement(query), "morning1", "xyz");
    } finally {
        conn.close();
    }
}

@Test
public void testIndexPriorityWritesToIndexHandler() throws Exception {
    RpcScheduler mock = Mockito.mock(RpcScheduler.class);
    PhoenixRpcScheduler scheduler = new PhoenixRpcScheduler(conf, mock, 200, 250);
    BalancedQueueRpcExecutor executor = new BalancedQueueRpcExecutor("test-queue", 1, 1, 1);
    scheduler.setIndexExecutorForTesting(executor);
    dispatchCallWithPriority(scheduler, 200);
    List<BlockingQueue<CallRunner>> queues = executor.getQueues();
    assertEquals(1, queues.size());
    BlockingQueue<CallRunner> queue = queues.get(0);
    queue.poll(20, TimeUnit.SECONDS);
    // try again, this time we tweak the ranges we support
    scheduler = new PhoenixRpcScheduler(conf, mock, 101, 110);
    scheduler.setIndexExecutorForTesting(executor);
    dispatchCallWithPriority(scheduler, 101);
    queue.poll(20, TimeUnit.SECONDS);
    Mockito.verify(mock, Mockito.times(2)).init(Mockito.any(Context.class));
    scheduler.stop();
    executor.stop();
}

/**
 * Test that we delegate to the passed {@link RpcScheduler} when the call priority is outside
 * the index range
 * @throws Exception
 */
@Test
public void testDelegateWhenOutsideRange() throws Exception {
    RpcScheduler mock = Mockito.mock(RpcScheduler.class);
    PhoenixRpcScheduler scheduler = new PhoenixRpcScheduler(conf, mock, 200, 250);
    dispatchCallWithPriority(scheduler, 100);
    dispatchCallWithPriority(scheduler, 251);
    // try again, this time we tweak the ranges we support
    scheduler = new PhoenixRpcScheduler(conf, mock, 101, 110);
    dispatchCallWithPriority(scheduler, 200);
    dispatchCallWithPriority(scheduler, 111);
    Mockito.verify(mock, Mockito.times(4)).init(Mockito.any(Context.class));
    Mockito.verify(mock, Mockito.times(4)).dispatch(Mockito.any(CallRunner.class));
    scheduler.stop();
}

@Test
public void ensureInstantiation() throws Exception {
    Configuration conf = new Configuration(false);
    conf.setClass(RSRpcServices.REGION_SERVER_RPC_SCHEDULER_FACTORY_CLASS, PhoenixRpcSchedulerFactory.class, RpcSchedulerFactory.class);
    // kinda lame that we copy the copy from the regionserver to do this and can't use a static
    // method, but meh
    try {
        Class<?> rpcSchedulerFactoryClass = conf.getClass(RSRpcServices.REGION_SERVER_RPC_SCHEDULER_FACTORY_CLASS, SimpleRpcSchedulerFactory.class);
        Object o = rpcSchedulerFactoryClass.newInstance();
        assertTrue(o instanceof PhoenixRpcSchedulerFactory);
    } catch (InstantiationException e) {
        assertTrue("Should not have got an exception when instantiing the rpc scheduler: " + e, false);
    } catch (IllegalAccessException e) {
        assertTrue("Should not have got an exception when instantiing the rpc scheduler: " + e, false);
    }
}

/**
 * Ensure that we can't configure the index and metadata priority ranges inside the hbase ranges
 * @throws Exception
 */
@Test
public void testValidateRpcPriorityRanges() throws Exception {
    Configuration conf = new Configuration(false);
    // standard configs should be fine
    PhoenixRpcSchedulerFactory factory = new PhoenixRpcSchedulerFactory();
    factory.create(conf, null);
    // test priorities less than HBase range
    setPriorities(conf, -4, -1);
    factory.create(conf, null);
    // test priorities greater than HBase range
    setPriorities(conf, 1001, 1002);
    factory.create(conf, null);
    // test priorities in HBase range
    setPriorities(conf, 1, 201);
    try {
        factory.create(conf, null);
        fail("Should not have allowed priorities in HBase range");
    } catch (IllegalArgumentException e) {
        // expected
    }
    setPriorities(conf, 1001, 1);
    try {
        factory.create(conf, null);
        fail("Should not have allowed priorities in HBase range");
    } catch (IllegalArgumentException e) {
        // expected
    }
    // test priorities in HBase range
    setPriorities(conf, 1001, HConstants.NORMAL_QOS);
    try {
        factory.create(conf, null);
        fail("Should not have allowed priorities in HBase range");
    } catch (IllegalArgumentException e) {
        // expected
    }
    setPriorities(conf, HConstants.NORMAL_QOS, 1001);
    try {
        factory.create(conf, null);
        fail("Should not have allowed priorities in HBase range");
    } catch (IllegalArgumentException e) {
        // expected
    }
    // test priorities in HBase range
    setPriorities(conf, 1001, HConstants.HIGH_QOS);
    try {
        factory.create(conf, null);
        fail("Should not have allowed priorities in HBase range");
    } catch (IllegalArgumentException e) {
        // expected
    }
    setPriorities(conf, HConstants.HIGH_QOS, 1001);
    try {
        factory.create(conf, null);
        fail("Should not have allowed priorities in HBase range");
    } catch (IllegalArgumentException e) {
        // expected
    }
}

