@Test
public void testExplainPlan() throws Exception {
    Connection conn = DriverManager.getConnection(getUrl());
    String query = "EXPLAIN SELECT s."supplier_id", "order_id", c.name, i.name, quantity, o."date" FROM " + JOIN_ORDER_TABLE_FULL_NAME + " o LEFT JOIN " + JOIN_CUSTOMER_TABLE_FULL_NAME + " c ON o."customer_id" = c."customer_id" AND c.name LIKE 'C%' LEFT JOIN " + JOIN_ITEM_TABLE_FULL_NAME + " i ON o."item_id" = i."item_id" RIGHT JOIN " + JOIN_SUPPLIER_TABLE_FULL_NAME + " s ON s."supplier_id" = i."supplier_id" WHERE i.name LIKE 'T%'";
    ResultSet rs = conn.createStatement().executeQuery(query);
    assertEquals("CLIENT PARALLEL 1-WAY FULL SCAN OVER " + JOIN_SUPPLIER_TABLE_DISPLAY_NAME + "
" + "    SERVER FILTER BY FIRST KEY ONLY
" + "    PARALLEL LEFT-JOIN TABLE 0
" + "        CLIENT PARALLEL 1-WAY FULL SCAN OVER " + JOIN_ORDER_TABLE_DISPLAY_NAME + "
" + "            PARALLEL LEFT-JOIN TABLE 0
" + "                CLIENT PARALLEL 1-WAY FULL SCAN OVER " + JOIN_CUSTOMER_TABLE_DISPLAY_NAME + "
" + "                    SERVER FILTER BY NAME LIKE 'C%'
" + "            PARALLEL LEFT-JOIN TABLE 1
" + "                CLIENT PARALLEL 1-WAY FULL SCAN OVER " + JOIN_ITEM_TABLE_DISPLAY_NAME + "
" + "    AFTER-JOIN SERVER FILTER BY I.NAME LIKE 'T%'", QueryUtil.getExplainPlan(rs));
}

@Test
public void testWhereClauseOptimization() throws Exception {
    PhoenixConnection pconn = DriverManager.getConnection(getUrl(), PropertiesUtil.deepCopy(TEST_PROPERTIES)).unwrap(PhoenixConnection.class);
    String queryTemplate = "SELECT t1.\"item_id\", t2.\"item_id\", t3.\"item_id\" FROM " + JOIN_ITEM_TABLE_FULL_NAME + " t1 " + "%s JOIN " + JOIN_ITEM_TABLE_FULL_NAME + " t2 ON t1.\"item_id\" = t2.\"item_id\" " + "%s JOIN " + JOIN_ITEM_TABLE_FULL_NAME + " t3 ON t1.\"item_id\" = t3.\"item_id\" " + "WHERE t1.\"item_id\" = '0000000001' AND t2.\"item_id\" = '0000000002' AND t3.\"item_id\" = '0000000003'";
    String query = String.format(queryTemplate, "INNER", "INNER");
    JoinTable joinTable = getJoinTable(query, pconn);
    assertEquals(1, joinTable.getTable().getPreFilters().size());
    assertEquals(1, joinTable.getJoinSpecs().get(0).getJoinTable().getTable().getPreFilters().size());
    assertEquals(1, joinTable.getJoinSpecs().get(1).getJoinTable().getTable().getPreFilters().size());
    query = String.format(queryTemplate, "INNER", "LEFT");
    joinTable = getJoinTable(query, pconn);
    assertEquals(1, joinTable.getTable().getPreFilters().size());
    assertEquals(1, joinTable.getJoinSpecs().get(0).getJoinTable().getTable().getPreFilters().size());
    assertEquals(0, joinTable.getJoinSpecs().get(1).getJoinTable().getTable().getPreFilters().size());
    query = String.format(queryTemplate, "INNER", "RIGHT");
    joinTable = getJoinTable(query, pconn);
    assertEquals(0, joinTable.getTable().getPreFilters().size());
    assertEquals(0, joinTable.getJoinSpecs().get(0).getJoinTable().getTable().getPreFilters().size());
    assertEquals(1, joinTable.getJoinSpecs().get(1).getJoinTable().getTable().getPreFilters().size());
    query = String.format(queryTemplate, "LEFT", "INNER");
    joinTable = getJoinTable(query, pconn);
    assertEquals(1, joinTable.getTable().getPreFilters().size());
    assertEquals(0, joinTable.getJoinSpecs().get(0).getJoinTable().getTable().getPreFilters().size());
    assertEquals(1, joinTable.getJoinSpecs().get(1).getJoinTable().getTable().getPreFilters().size());
    query = String.format(queryTemplate, "LEFT", "LEFT");
    joinTable = getJoinTable(query, pconn);
    assertEquals(1, joinTable.getTable().getPreFilters().size());
    assertEquals(0, joinTable.getJoinSpecs().get(0).getJoinTable().getTable().getPreFilters().size());
    assertEquals(0, joinTable.getJoinSpecs().get(1).getJoinTable().getTable().getPreFilters().size());
    query = String.format(queryTemplate, "LEFT", "RIGHT");
    joinTable = getJoinTable(query, pconn);
    assertEquals(0, joinTable.getTable().getPreFilters().size());
    assertEquals(0, joinTable.getJoinSpecs().get(0).getJoinTable().getTable().getPreFilters().size());
    assertEquals(1, joinTable.getJoinSpecs().get(1).getJoinTable().getTable().getPreFilters().size());
    query = String.format(queryTemplate, "RIGHT", "INNER");
    joinTable = getJoinTable(query, pconn);
    assertEquals(0, joinTable.getTable().getPreFilters().size());
    assertEquals(1, joinTable.getJoinSpecs().get(0).getJoinTable().getTable().getPreFilters().size());
    assertEquals(1, joinTable.getJoinSpecs().get(1).getJoinTable().getTable().getPreFilters().size());
    query = String.format(queryTemplate, "RIGHT", "RIGHT");
    joinTable = getJoinTable(query, pconn);
    assertEquals(0, joinTable.getTable().getPreFilters().size());
    assertEquals(0, joinTable.getJoinSpecs().get(0).getJoinTable().getTable().getPreFilters().size());
    assertEquals(1, joinTable.getJoinSpecs().get(1).getJoinTable().getTable().getPreFilters().size());
}

