        conn.createStatement().execute("CREATE TABLE PLATFORM_ENTITY.GLOBAL_TABLE (
" + "    ORGANIZATION_ID CHAR(15) NOT NULL,
" + "    KEY_PREFIX CHAR(3) NOT NULL,
" + "    CREATED_DATE DATE,
" + "    CREATED_BY CHAR(15),
" + "    CONSTRAINT PK PRIMARY KEY (
" + "        ORGANIZATION_ID,
" + "        KEY_PREFIX
" + "    )
" + ") VERSIONS=1, IMMUTABLE_ROWS=true, MULTI_TENANT=true");
        conn.createStatement().execute("CREATE VIEW PLATFORM_ENTITY.GLOBAL_VIEW  (
" + "    INT1 BIGINT NOT NULL,
" + "    DOUBLE1 DECIMAL(12, 3),
" + "    IS_BOOLEAN BOOLEAN,
" + "    TEXT1 VARCHAR,
" + "    CONSTRAINT PKVIEW PRIMARY KEY
" + "    (
" + "        INT1
" + "    )
" + ")
" + "AS SELECT * FROM PLATFORM_ENTITY.GLOBAL_TABLE WHERE KEY_PREFIX = '123'");
        conn.createStatement().execute("CREATE INDEX GLOBAL_INDEX
" + "ON PLATFORM_ENTITY.GLOBAL_VIEW (TEXT1 DESC, INT1)
" + "INCLUDE (CREATED_BY, DOUBLE1, IS_BOOLEAN, CREATED_DATE)");
        String query = "SELECT DOUBLE1 FROM PLATFORM_ENTITY.GLOBAL_VIEW
" + "WHERE ORGANIZATION_ID = '00Dxx0000002Col' AND TEXT1='Test' AND INT1=1";
        QueryPlan plan = getOptimizedQueryPlan(query);
        assertEquals("PLATFORM_ENTITY.GLOBAL_VIEW", plan.getContext().getCurrentTable().getTable().getName().getString());
        query = "SELECT DOUBLE1 FROM PLATFORM_ENTITY.GLOBAL_VIEW
" + "WHERE ORGANIZATION_ID = '00Dxx0000002Col' AND TEXT1='Test'";
        plan = getOptimizedQueryPlan(query);
        assertEquals("PLATFORM_ENTITY.GLOBAL_INDEX", plan.getContext().getCurrentTable().getTable().getName().getString());
    }
}

