            assertTrue(c1.getSize() == 20);
            // we waited some time before the allocate happened
            Mockito.verify(gmm, atLeastOnce()).waitForBytesToFree(anyLong(), anyLong());
            c3.close();
            assertTrue(rmm2.getAvailableMemory() == rmm2.getMaxMemory());
            latch.countDown();
        }
    };
    t1.start();
    t2.start();
