@Test
public void booleanLogic() {
    assertTrue(PBoolean.INSTANCE.toObject(PDataType.TRUE_BYTES, SortOrder.ASC) == PBoolean.INSTANCE.toObject(PDataType.FALSE_BYTES, SortOrder.DESC));
    assertTrue(PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(true), SortOrder.ASC) == PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false), SortOrder.DESC));
    assertTrue(PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(true, SortOrder.ASC)) == PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false, SortOrder.DESC)));
    assertFalse(PBoolean.INSTANCE.toObject(PDataType.FALSE_BYTES, SortOrder.ASC) == PBoolean.INSTANCE.toObject(PDataType.FALSE_BYTES, SortOrder.DESC));
    assertFalse(PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false), SortOrder.ASC) == PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false), SortOrder.DESC));
    assertFalse(PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false, SortOrder.ASC)) == PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false, SortOrder.DESC)));
}

@Test
public void descSortOrderTransformsOp() {
    for (CompareOp op : CompareOp.values()) {
        CompareOp oppositeOp = SortOrder.DESC.transform(op);
        switch(op) {
            case EQUAL:
                assertSame(CompareOp.EQUAL, oppositeOp);
                break;
            case GREATER:
                assertSame(CompareOp.LESS, oppositeOp);
                break;
            case GREATER_OR_EQUAL:
                assertSame(CompareOp.LESS_OR_EQUAL, oppositeOp);
                break;
            case LESS:
                assertSame(CompareOp.GREATER, oppositeOp);
                break;
            case LESS_OR_EQUAL:
                assertSame(CompareOp.GREATER_OR_EQUAL, oppositeOp);
                break;
            case NOT_EQUAL:
                assertSame(CompareOp.NOT_EQUAL, oppositeOp);
                break;
            case NO_OP:
                assertSame(CompareOp.NO_OP, oppositeOp);
                break;
        }
    }
}

